using System;
using System.Collections;
using System.Collections.Generic;
using Newtonsoft.Json;

namespace BIMMR.Inspection
{
    /// <summary>
    /// Event-level evidence record: one per confirmed selection (one inspection event).
    /// <see cref="InspectionRecord"/> stays per element and carries the live status;
    /// an evidence record is the snapshot that the paired HTML/JSON report exports.
    ///
    /// The eleven required fields of Section 3.3.4 are <see cref="RequiredFields"/>.
    /// Identifiers and timestamps are copied from the selection, never generated by the
    /// LLM; the LLM narrative is a separate field.
    /// </summary>
    [Serializable]
    public class EvidenceRecord
    {
        [JsonProperty("event_id")] public string eventId;
        [JsonProperty("session_id")] public string sessionId;
        [JsonProperty("participant_id")] public string participantId;
        [JsonProperty("condition")] public string condition;
        [JsonProperty("build_version")] public string buildVersion;

        // ---- required fields ----------------------------------------------
        [JsonProperty("element_id")] public string elementId;
        [JsonProperty("timestamp")] public string timestamp;
        [JsonProperty("module_id")] public string moduleId;
        [JsonProperty("category")] public string category;
        [JsonProperty("status")] public string status;
        [JsonProperty("screenshot_path")] public string screenshotPath;
        [JsonProperty("notes")] public string notes;
        [JsonProperty("element_name")] public string elementName;
        [JsonProperty("element_type")] public string elementType;
        [JsonProperty("geometric_descriptors")] public string geometricDescriptors;
        [JsonProperty("report_status")] public string reportStatus;

        // ---- supporting fields --------------------------------------------
        [JsonProperty("element_id_is_fallback")] public bool elementIdIsFallback;
        [JsonProperty("level")] public string level;
        [JsonProperty("camera_pose")] public string cameraPose;
        [JsonProperty("ray_hit_point")] public string rayHitPoint;
        [JsonProperty("llm_narrative")] public string llmNarrative;
        [JsonProperty("llm_narrative_flagged")] public bool llmNarrativeFlagged;

        /// <summary>SHA-256 of this record's canonical JSON with this field removed (U8).</summary>
        [JsonProperty("json_sha256")] public string jsonSha256;

        [JsonIgnore] public bool superseded;

        public static readonly string[] RequiredFields =
        {
            "element_id", "timestamp", "module_id", "category", "status", "screenshot_path",
            "notes", "element_name", "element_type", "geometric_descriptors", "report_status"
        };

        public string Field(string name)
        {
            switch (name)
            {
                case "element_id": return elementIdIsFallback ? "" : elementId;
                case "timestamp": return timestamp;
                case "module_id": return moduleId;
                case "category": return category;
                case "status": return status;
                case "screenshot_path": return screenshotPath;
                case "notes": return notes;
                case "element_name": return elementName;
                case "element_type": return elementType;
                case "geometric_descriptors": return geometricDescriptors;
                case "report_status": return reportStatus;
                default: return null;
            }
        }
    }

    /// <summary>
    /// Implemented by the conversational LLM component so the exporter can request a
    /// report narrative for each record without a hard dependency on it.
    /// </summary>
    public interface IReportNarrativeService
    {
        bool NarrativeAvailable { get; }
        /// <summary>Request a narrative for one record. onDone receives the text and
        /// whether the response validator flagged it (unsupported ids or values).</summary>
        IEnumerator RequestNarrative(EvidenceRecord record, Action<string, bool> onDone);
    }
}
